import{_ as t,o as a,c as i,ag as n}from"./chunks/framework.BpFM782D.js";const u=JSON.parse('{"title":"feature-kickoff","description":"","frontmatter":{},"headers":[],"relativePath":"en/skills/feature-kickoff.md","filePath":"en/skills/feature-kickoff.md"}'),r={name:"en/skills/feature-kickoff.md"};function s(o,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="feature-kickoff" tabindex="-1">feature-kickoff <a class="header-anchor" href="#feature-kickoff" aria-label="Permalink to &quot;feature-kickoff&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Name</td><td>feature-kickoff</td></tr><tr><td>Description</td><td>Feature development kickoff flow. Auto-detects feature scale (Light/Standard/Full) and selects the appropriate depth of kickoff process.</td></tr><tr><td>Source Directory</td><td><code>skills/feature-kickoff/</code></td></tr></tbody></table><hr><h1 id="feature-kickoff-1" tabindex="-1">Feature Kickoff <a class="header-anchor" href="#feature-kickoff-1" aria-label="Permalink to &quot;Feature Kickoff&quot;">​</a></h1><p>Feature development startup workflow. Intelligently selects the startup depth based on feature size — avoiding over-process for small features and skipped steps for large ones.</p><h2 id="phase-0-size-classification" tabindex="-1">Phase 0: Size Classification <a class="header-anchor" href="#phase-0-size-classification" aria-label="Permalink to &quot;Phase 0: Size Classification&quot;">​</a></h2><p>When receiving a feature request, first determine its size. This step is critical — different sizes require different depths of preparation. Spending too much time preparing for a small feature is wasteful; insufficient preparation for a large feature leads to rework.</p><table tabindex="0"><thead><tr><th>Level</th><th>Criteria</th><th>Examples</th></tr></thead><tbody><tr><td><strong>Light</strong></td><td>Single component/file, clear logic, &lt; 2hr</td><td>Adjust button style, update copy, add a static page</td></tr><tr><td><strong>Standard</strong></td><td>2–5 files, involves existing patterns, half-day to 1 day</td><td>Add a list page, integrate a new API, refactor a component</td></tr><tr><td><strong>Full</strong></td><td>Cross-module, requires architectural decisions, &gt; 1 day</td><td>Add a complete feature module, major refactor, add auth flow</td></tr></tbody></table><p>When unsure of the size, err on the side of the higher level — over-preparing is better than under-preparing.</p><h3 id="steps-by-level" tabindex="-1">Steps by Level <a class="header-anchor" href="#steps-by-level" aria-label="Permalink to &quot;Steps by Level&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Step</th><th style="text-align:center;">Light</th><th style="text-align:center;">Standard</th><th style="text-align:center;">Full</th></tr></thead><tbody><tr><td>Phase 1: Read Design Guidelines</td><td style="text-align:center;">Quick scan</td><td style="text-align:center;">Key reading</td><td style="text-align:center;">Full reading</td></tr><tr><td>Phase 2: Create Worktree</td><td style="text-align:center;">Skip</td><td style="text-align:center;">Recommended</td><td style="text-align:center;">Required</td></tr><tr><td>Phase 3: Task Breakdown</td><td style="text-align:center;">Mental checklist</td><td style="text-align:center;">Structured list</td><td style="text-align:center;">Delegate to requirement-analyzer</td></tr><tr><td>Phase 4: Spec Management</td><td style="text-align:center;">Skip</td><td style="text-align:center;">As needed</td><td style="text-align:center;">OpenSpec</td></tr></tbody></table><hr><h2 id="phase-1-read-design-guidelines" tabindex="-1">Phase 1: Read Design Guidelines <a class="header-anchor" href="#phase-1-read-design-guidelines" aria-label="Permalink to &quot;Phase 1: Read Design Guidelines&quot;">​</a></h2><p>Before writing code, understand the design intent. What to read and how deeply depends on the size and type of feature.</p><h3 id="light-quick-scan" tabindex="-1">Light: Quick Scan <a class="header-anchor" href="#light-quick-scan" aria-label="Permalink to &quot;Light: Quick Scan&quot;">​</a></h3><p>Read only the files directly related to the change:</p><ul><li>The blueprint spec for that component (if available)</li><li>The relevant section of <code>docs/DESIGN_GUIDELINE.md</code></li></ul><h3 id="standard-key-reading" tabindex="-1">Standard: Key Reading <a class="header-anchor" href="#standard-key-reading" aria-label="Permalink to &quot;Standard: Key Reading&quot;">​</a></h3><p>Read selectively based on feature type:</p><table tabindex="0"><thead><tr><th>Feature Type</th><th>Priority Reading</th></tr></thead><tbody><tr><td>New page</td><td><code>information-architecture/routes.md</code> → <code>navigation.md</code> → relevant <code>design-system/components/</code></td></tr><tr><td>API integration</td><td><code>standards/api-integration.md</code> → <code>standards/content-model-api-db-spec.md</code></td></tr><tr><td>UI component</td><td><code>design-system/tokens/design-tokens.md</code> → <code>design-system/components/frontstage/</code></td></tr><tr><td>Content change</td><td>Relevant <code>content/pages/</code> directory → <code>information-architecture/page-inventory.md</code></td></tr></tbody></table><h3 id="full-complete-reading" tabindex="-1">Full: Complete Reading <a class="header-anchor" href="#full-complete-reading" aria-label="Permalink to &quot;Full: Complete Reading&quot;">​</a></h3><p>Read in order:</p><ol><li><code>blueprint/architecture/overview.md</code> → Technical architecture overview</li><li><code>blueprint/init-plans/frontstage-web.md</code> → Implementation plan (confirm Phase and Change numbers)</li><li><code>blueprint/information-architecture/</code> → Routes, navigation, user flows</li><li><code>blueprint/design-system/</code> → Relevant component specs and tokens</li><li><code>blueprint/standards/</code> → Relevant standards documents</li></ol><p><strong>Purpose</strong>: Ensure implementation aligns with design guidelines and avoids rework. If the project has no <code>blueprint/</code> directory, read <code>README.md</code>, <code>CLAUDE.md</code>, or other architectural documents instead.</p><hr><h2 id="phase-2-create-a-worktree-for-isolated-development" tabindex="-1">Phase 2: Create a Worktree for Isolated Development <a class="header-anchor" href="#phase-2-create-a-worktree-for-isolated-development" aria-label="Permalink to &quot;Phase 2: Create a Worktree for Isolated Development&quot;">​</a></h2><p>Worktrees let you develop a new feature in a separate directory without affecting the state of the main branch. This is especially useful when working on multiple features simultaneously or for long-running development.</p><h3 id="when-it-s-needed" tabindex="-1">When It&#39;s Needed <a class="header-anchor" href="#when-it-s-needed" aria-label="Permalink to &quot;When It&#39;s Needed&quot;">​</a></h3><ul><li><strong>Light</strong>: Skip — work directly on the current branch</li><li><strong>Standard</strong>: Recommended — if expecting &gt; 3 commits</li><li><strong>Full</strong>: Required — isolate large feature development</li></ul><h3 id="how-to-create" tabindex="-1">How to Create <a class="header-anchor" href="#how-to-create" aria-label="Permalink to &quot;How to Create&quot;">​</a></h3><p>Use Claude Code&#39;s <code>EnterWorktree</code> tool (type &quot;worktree&quot; to trigger it). The branch will be named automatically.</p><p>If <code>EnterWorktree</code> is unavailable, create manually:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> worktree</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .worktrees/feature-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h3 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h3><ul><li>Use the full worktree path for all file operations</li><li>Merge back to the main branch after completion, then clean up the worktree</li></ul><hr><h2 id="phase-3-task-breakdown" tabindex="-1">Phase 3: Task Breakdown <a class="header-anchor" href="#phase-3-task-breakdown" aria-label="Permalink to &quot;Phase 3: Task Breakdown&quot;">​</a></h2><p>Different levels use different depths of breakdown.</p><h3 id="light-mental-checklist" tabindex="-1">Light: Mental Checklist <a class="header-anchor" href="#light-mental-checklist" aria-label="Permalink to &quot;Light: Mental Checklist&quot;">​</a></h3><p>List 2–5 steps directly in the response — no formal document needed:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tasks:</span></span>
<span class="line"><span>1. Modify the style of XXX component</span></span>
<span class="line"><span>2. Verify responsive behavior</span></span>
<span class="line"><span>3. Run lint to confirm</span></span></code></pre></div><h3 id="standard-structured-list" tabindex="-1">Standard: Structured List <a class="header-anchor" href="#standard-structured-list" aria-label="Permalink to &quot;Standard: Structured List&quot;">​</a></h3><p>Use the TaskCreate tool to create a task list (if unavailable, use a markdown checklist):</p><p>Each task should include:</p><ul><li><strong>subject</strong>: What to do (imperative sentence, e.g., &quot;Create NewsCard component&quot;)</li><li><strong>description</strong>: Completion criteria and technical details</li><li><strong>activeForm</strong>: Present-progressive description (e.g., &quot;Creating NewsCard component&quot;)</li><li>Mark dependencies between tasks (<code>blockedBy</code>)</li></ul><p><strong>Rhythm</strong>: Create all tasks → Mark in_progress in order → Complete → Mark completed → Move to next</p><h3 id="full-delegate-to-requirement-analyzer-do-not-break-down-yourself" tabindex="-1">Full: Delegate to requirement-analyzer (do not break down yourself) <a class="header-anchor" href="#full-delegate-to-requirement-analyzer-do-not-break-down-yourself" aria-label="Permalink to &quot;Full: Delegate to requirement-analyzer (do not break down yourself)&quot;">​</a></h3><p>Full-level requirement breakdown <strong>must be delegated</strong> to the <code>requirement-analyzer</code> skill. This is not a recommendation — it is a process requirement. Here&#39;s why:</p><ul><li><code>requirement-analyzer</code> performs <strong>multi-round conversational requirement clarification</strong> (Phase 1), surfacing edge cases you might miss on your own</li><li>It has a systematic <strong>Edge Cases scan</strong> (6 dimensions: input, state, permissions, network, device, data), which is more comprehensive than manual enumeration</li><li>Its feature breakdown output includes <strong>priority levels (P0/P1/P2) and complexity estimates</strong>, which feature-kickoff does not provide</li></ul><p>Even if you already have a thorough understanding of the feature, still delegate — because the value of requirement-analyzer lies in its <strong>structured verification process</strong>, not knowledge supplementation.</p><p><strong>How to delegate:</strong></p><p>Tell the user you need to perform requirement analysis first, then invoke the requirement-analyzer skill:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I&#39;ll use requirement-analyzer to perform a complete requirement analysis and task breakdown first.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/requirement-analyzer</span></span></code></pre></div><p>After requirement-analyzer produces its output, use TaskCreate to convert the feature points (FE-001, FE-002, ...) into trackable tasks.</p><hr><h2 id="phase-4-spec-management-full-level-only" tabindex="-1">Phase 4: Spec Management (Full level only) <a class="header-anchor" href="#phase-4-spec-management-full-level-only" aria-label="Permalink to &quot;Phase 4: Spec Management (Full level only)&quot;">​</a></h2><p>For large features involving architectural decisions or spec changes, use OpenSpec for tracking:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/opsx:new         → Create a new change (with proposal)</span></span>
<span class="line"><span>/opsx:continue    → Incrementally build artifacts (design → specs → tasks)</span></span>
<span class="line"><span>/opsx:apply       → Implement according to tasks</span></span>
<span class="line"><span>/opsx:verify      → Verify implementation matches spec</span></span>
<span class="line"><span>/opsx:archive     → Archive after completion</span></span></code></pre></div><p><strong>Decision criteria</strong>: If the feature does not involve spec or architectural changes, skip this step. Simple feature development doesn&#39;t need OpenSpec — it&#39;s designed for significant changes that require a decision record.</p><hr><h2 id="completion-checks" tabindex="-1">Completion Checks <a class="header-anchor" href="#completion-checks" aria-label="Permalink to &quot;Completion Checks&quot;">​</a></h2><p>Confirm based on level:</p><h3 id="light" tabindex="-1">Light <a class="header-anchor" href="#light" aria-label="Permalink to &quot;Light&quot;">​</a></h3><ul><li>[ ] Scope of changes understood</li><li>[ ] Code complete</li><li>→ Hand off to <code>quality-gate</code>: run <code>npm run lint</code> and relevant tests</li></ul><h3 id="standard" tabindex="-1">Standard <a class="header-anchor" href="#standard" aria-label="Permalink to &quot;Standard&quot;">​</a></h3><ul><li>[ ] Relevant blueprint or architectural documents read</li><li>[ ] Tasks broken down and tracked</li><li>[ ] Worktree created (if applicable)</li><li>→ Hand off to <code>quality-gate</code>: complete quality gate (build + types + lint + test)</li><li>→ Hand off to <code>git-workflow</code>: commit at task granularity, then open a PR</li></ul><h3 id="full" tabindex="-1">Full <a class="header-anchor" href="#full" aria-label="Permalink to &quot;Full&quot;">​</a></h3><ul><li>[ ] Relevant blueprint sections fully read</li><li>[ ] Worktree created</li><li>[ ] Requirements fully analyzed by <code>requirement-analyzer</code> (not broken down manually)</li><li>[ ] requirement-analyzer output converted to TaskCreate tasks</li><li>[ ] Spec changes tracked with OpenSpec (if applicable)</li><li>[ ] All tasks completed and marked as completed</li><li>→ <strong>Hand off to <code>quality-gate</code></strong>: full check (build + types + lint + test + security)</li><li>→ <strong>Hand off to <code>git-workflow</code></strong>: incremental commits + PR</li><li>→ <strong>Hand off to <code>doc-consistency</code></strong>: required when blueprint, IA, or architectural documents are modified — ensures related documents are in sync</li></ul><hr><h2 id="skill-integration-overview" tabindex="-1">Skill Integration Overview <a class="header-anchor" href="#skill-integration-overview" aria-label="Permalink to &quot;Skill Integration Overview&quot;">​</a></h2><p>The following skills are used in the feature-kickoff workflow, in chronological order:</p><table tabindex="0"><thead><tr><th>Timing</th><th>Skill</th><th>Trigger Condition</th></tr></thead><tbody><tr><td>Phase 3 (Full)</td><td><code>requirement-analyzer</code></td><td>Full level must delegate requirement analysis</td></tr><tr><td>Phase 4 (Full)</td><td><code>opsx:new</code> / <code>opsx:continue</code></td><td>When spec or architectural changes are involved</td></tr><tr><td>After completion</td><td><code>quality-gate</code></td><td>All levels; run quality gate</td></tr><tr><td>On commit</td><td><code>git-workflow</code></td><td>Standard/Full; commit at task granularity</td></tr><tr><td>When editing docs</td><td><code>doc-consistency</code></td><td>When blueprint/IA/architectural documents are modified</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Commit messages use conventional commit prefix + Traditional Chinese description</li><li>Use the <code>checkpoint:</code> prefix when committing at important milestones</li><li>When modifying information-architecture documents, <code>doc-consistency</code> will automatically trigger a sync check</li></ul>`,74)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
